$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$state=Join-Path $root '.demo-processes.json';if(!(Test-Path $state)){Write-Host 'No demo state file found.';exit 0};$data=Get-Content $state|ConvertFrom-Json;$ids=@($data.backend_pid,$data.frontend_pid);foreach($port in @($data.backend_port,$data.frontend_port)){try{$ids+=@(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction Stop|Select-Object -ExpandProperty OwningProcess)}catch{}};foreach($id in ($ids|Select-Object -Unique)){if(Get-Process -Id $id -ErrorAction SilentlyContinue){Stop-Process -Id $id -Force;Write-Host "Stopped demo process $id"}};Remove-Item $state -Force
